 edCustNo(id,el){const v=el.value.trim(),AF=window.AAOrderForm,rec=AF&&v?AF.masterByNumber(v):null;if(rec){window.edCls(id,'co',rec.name);return}if(v){toast('Customer number not found in the Customer master');R()}},
