function approveWhy(s){return s.rejected?'This order was rejected':s.linked?'This order is linked to a Case':s.createdCaseId?'A Case was already created for this order':!s.unlocked?'Choose Create New Case to edit and approve this order':clsMissing(s)?'Complete the AI Classification fields marked *':custIssue(s)}
